import sqlite3


class Archivio:
    def __init__(self, file):
        self.con = sqlite3.connect(file)
        with self.con:
            self.con.execute(
                "CREATE TABLE IF NOT EXISTS prove (provino TEXT PRIMARY KEY, materiale TEXT NOT NULL, "
                "data TEXT NOT NULL, Rm REAL CHECK (Rm > 0))"
            )

    def importa(self, prove):
        sbagliate = [p[0] for p in prove if p[3] <= 0]
        if sbagliate:
            raise ValueError(f"Rm non positivo: {', '.join(sbagliate)}")
        prima = self.con.total_changes
        with self.con:
            self.con.executemany("INSERT OR IGNORE INTO prove VALUES (?, ?, ?, ?)", prove)
        return self.con.total_changes - prima

    def statistiche(self, materiale, dal=None):
        sql = "SELECT COUNT(*), AVG(Rm), MIN(Rm) FROM prove WHERE materiale = ?"
        parametri = [materiale]
        if dal is not None:
            sql += " AND data >= ?"
            parametri.append(dal)
        return self.con.execute(sql, parametri).fetchone()

    def chiudi(self):
        self.con.close()
